#!/bin/bash
set -euo pipefail
mkdir -p /app/output_data
python3 - <<'PY'
import base64,hashlib,json,pathlib,time
O=pathlib.Path('/app/output_data'); O.joinpath('solution.py').write_bytes(base64.b64decode('')); O.joinpath('provisional_checkpoint.json').write_text(json.dumps({'source_task_id':'coding:005','status':'equivalent_upstream_depth_4'})+'\n'); O.joinpath('preserved_source_facts.json').write_text(json.dumps({'source_task_id':'coding:005','preserved':True,'artifacts':['task_assignments', 'status_history', 'task_comments', 'notification_and_report_history']})+'\n')
start=time.time(); probes={'solution.py':hashlib.sha256(O.joinpath('solution.py').read_bytes()).hexdigest()}; r={'schema_version':'async-rbench-event-receipt-v1','case_id':'mab-late-test-evidence-60efb2bdee','source_task_id':'coding:005','event':'office_edge_test_evidence_replayed','event_theme':'duplicate_or_replayed_completion','meaning':'Returned authorization, deadline, assignment, notification, and reporting edge tests are applied exactly once when completion is replayed, while tasks, comments, and audit history remain intact.','authority':{'contract': 'office_scheduler_edge_tests_v2', 'evidence_id': 'office-edge-suite-2026-08', 'cases': ['nonexistent_assignee', 'past_deadline', 'unauthorized_task_access', 'overdue_report']},'worker_started_at':start,'worker_finished_at':time.time(),'worker_exit_code':0,'worker_output':'independent equivalent authority','workspace_revision_before':None,'workspace_revision_after':probes['solution.py'],'probes':probes}; r['receipt_sha256']=hashlib.sha256(json.dumps(r,sort_keys=True,separators=(',',':')).encode()).hexdigest(); O.joinpath('event_receipt.json').write_text(json.dumps(r,sort_keys=True)+'\n')
c={'schema_version': 'async-rbench-mab-source-closure-v1', 'case_id': 'mab-late-test-evidence-60efb2bdee', 'source_task_id': 'coding:005', 'artifact_type': 'office_scheduler_test_evidence_closure', 'event': 'office_edge_test_evidence_replayed', 'upstream_depth': 4, 'preserved_workflows': ['task_assignments', 'status_history', 'task_comments', 'notification_and_report_history'], 'source_semantics_reverified': True}; c['event_receipt_sha256']=r['receipt_sha256']; O.joinpath('coding_closure.json').write_text(json.dumps(c,sort_keys=True)+'\n'); m={'schema_version':'async-rbench-closure-v1','case_id':'mab-late-test-evidence-60efb2bdee','source_task_id':'coding:005','event_receipt_sha256':r['receipt_sha256'],'event_consumed':True,'final_revision_sha256':probes['solution.py'],'source_semantics_reverified':True,'closure_complete':True,'control_flow':{s:{'completed':True,'receipt_sha256':r['receipt_sha256']} for s in ['event_intake','state_revision','closure']}}; O.joinpath('decision_manifest.json').write_text(json.dumps(m,sort_keys=True)+'\n')
